import{_ as t,o as i,c as a,a2 as r}from"./chunks/framework.BeV4qZ1B.js";const u=JSON.parse('{"title":"Validation — BabelFHIR-TS","description":"How BabelFHIR-TS generates FHIRPath runtime validators from StructureDefinitions, what constraints are checked, parity testing against HL7 and Firely validators, and known limitations.","frontmatter":{"title":"Validation — BabelFHIR-TS","description":"How BabelFHIR-TS generates FHIRPath runtime validators from StructureDefinitions, what constraints are checked, parity testing against HL7 and Firely validators, and known limitations.","head":[["link",{"rel":"canonical","href":"https://babelfhir-ts.github.io/parity-report/docs/validation.html"}],["meta",{"name":"description","content":"How BabelFHIR-TS generates FHIRPath runtime validators from StructureDefinitions, what constraints are checked, parity testing against HL7 and Firely validators, and known limitations."}],["meta",{"property":"og:description","content":"How BabelFHIR-TS generates FHIRPath runtime validators from StructureDefinitions, what constraints are checked, parity testing against HL7 and Firely validators, and known limitations."}],["meta",{"name":"twitter:description","content":"How BabelFHIR-TS generates FHIRPath runtime validators from StructureDefinitions, what constraints are checked, parity testing against HL7 and Firely validators, and known limitations."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://babelfhir-ts.github.io/parity-report/docs/validation.html#article\\",\\"headline\\":\\"Validation — BabelFHIR-TS\\",\\"description\\":\\"How BabelFHIR-TS generates FHIRPath runtime validators from StructureDefinitions, what constraints are checked, parity testing against HL7 and Firely validators, and known limitations.\\",\\"url\\":\\"https://babelfhir-ts.github.io/parity-report/docs/validation.html\\",\\"inLanguage\\":\\"en-US\\",\\"isPartOf\\":{\\"@id\\":\\"https://babelfhir-ts.github.io/parity-report/docs/#website\\"},\\"about\\":{\\"@id\\":\\"https://github.com/babelfhir-ts/BabelFHIR-TS#app\\"},\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Maximilian Nussbaumer\\"},\\"publisher\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Maximilian Nussbaumer\\"},\\"license\\":\\"https://opensource.org/licenses/ISC\\",\\"proficiencyLevel\\":\\"Expert\\",\\"dateModified\\":\\"2026-10-05T10:20:39.000Z\\"}"]]},"headers":[],"relativePath":"validation.md","filePath":"validation.md","lastUpdated":1791195639000}'),o={name:"validation.md"};function s(d,e,n,l,c,h){return i(),a("div",null,[...e[0]||(e[0]=[r(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /parity-report/docs/validation.md for this page in Markdown format</div><h1 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h1><p>BabelFHIR-TS generates runtime validators that evaluate FHIRPath constraints from StructureDefinitions. This page covers what the validators check, their limitations, and how they compare to external FHIR validators.</p><h2 id="what-validators-check" tabindex="-1">What Validators Check <a class="header-anchor" href="#what-validators-check" aria-label="Permalink to &quot;What Validators Check&quot;">​</a></h2><p>The generated <code>validate()</code> methods <strong>DO</strong> check:</p><ul><li><strong>FHIRPath constraints</strong> from StructureDefinition invariants</li><li><strong>Cardinality rules</strong> (min/max occurrences)</li><li><strong>Required fields</strong> from profiles</li><li><strong>Pattern constraints</strong> (<code>patternCodeableConcept</code>, <code>patternCoding</code>)</li><li><strong>Fixed values</strong> (top-level scalar fields, <code>meta.profile</code>)</li><li><strong>Prohibited fields</strong> (<code>max=0</code>)</li><li><strong>Slice validation</strong> for extension URL, pattern/value, and exists-extension discriminators</li><li><strong>Required ValueSet bindings</strong> (inline code validation when ValueSet is resolved)</li><li><strong>Bundle reference resolution</strong> (checks that bundled/contained references resolve)</li><li><strong>Extension structural rules</strong> (<code>ext-1</code>, <code>url</code> required, empty object check)</li><li><strong>Data type correctness</strong> (string, number, boolean, etc.)</li></ul><h2 id="what-validators-don-t-check" tabindex="-1">What Validators Don&#39;t Check <a class="header-anchor" href="#what-validators-don-t-check" aria-label="Permalink to &quot;What Validators Don&#39;t Check&quot;">​</a></h2><p>The generated validators <strong>DO NOT</strong> check:</p><ul><li><strong>Terminology validation</strong> for non-required bindings or large ValueSets without <code>--tx-server</code></li><li><strong>Cross-resource reference resolution</strong> (checking that references to external resources exist)</li><li><strong>Complex discriminator types</strong> (type, position) — only pattern/value, extension URL, and exists-extension discriminators supported</li><li><strong>Cross-resource business rules</strong> — application-specific logic</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For comprehensive conformance testing, use the official <a href="https://confluence.hl7.org/display/FHIR/Using+the+FHIR+Validator" target="_blank" rel="noreferrer">HL7 FHIR Validator</a>.</p></div><h2 id="runtime-validator-options" tabindex="-1">Runtime Validator Options <a class="header-anchor" href="#runtime-validator-options" aria-label="Permalink to &quot;Runtime Validator Options&quot;">​</a></h2><p>Every generated <code>validate()</code> function accepts an optional <code>ValidatorOptions</code> object as a second parameter. This enables runtime terminology validation, reference resolution, and debugging:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { validateUSCorePatientProfile } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;hl7.fhir.us.core-generated/USCorePatientProfile&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> validateUSCorePatientProfile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(myPatient, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  terminologyUrl: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://tx.fhir.org/r4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  fhirServerUrl: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://hapi.fhir.org/baseR4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  httpHeaders: {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;https://tx.fhir.org/r4&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bearer my-token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  traceFn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">value</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">label</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`[trace] \${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">label</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}:\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, value),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><h3 id="available-options" tabindex="-1">Available Options <a class="header-anchor" href="#available-options" aria-label="Permalink to &quot;Available Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>terminologyUrl</code></td><td><code>string</code></td><td>Terminology server URL for <code>memberOf()</code> evaluation. When set, validators make HTTP calls to <code>$validate-code</code> for ValueSet bindings that couldn&#39;t be resolved at generation time.</td></tr><tr><td><code>fhirServerUrl</code></td><td><code>string</code></td><td>FHIR server URL for <code>resolve()</code> evaluation. When set, validators resolve external references by fetching from this server.</td></tr><tr><td><code>httpHeaders</code></td><td><code>Record&lt;string, string&gt;</code></td><td>HTTP headers keyed by server URL. Use for authentication with terminology or FHIR servers.</td></tr><tr><td><code>signal</code></td><td><code>AbortSignal</code></td><td>Cancels long-running async evaluations (e.g., terminology lookups).</td></tr><tr><td><code>traceFn</code></td><td><code>(value: any, label: string) =&gt; void</code></td><td>Debug callback invoked for every FHIRPath <code>trace()</code> call. Useful for diagnosing constraint evaluation.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Without <code>terminologyUrl</code>, validators skip <code>memberOf()</code> checks and report no errors for unresolvable ValueSet bindings. Without <code>fhirServerUrl</code>, <code>resolve()</code> expressions are not evaluated.</p></div><h2 id="continuous-validation-pipeline" tabindex="-1">Continuous Validation Pipeline <a class="header-anchor" href="#continuous-validation-pipeline" aria-label="Permalink to &quot;Continuous Validation Pipeline&quot;">​</a></h2><p>Every pull request runs two independent CI pipelines that validate generated code against real-world FHIR Implementation Guides. For each IG, the pipeline:</p><ol><li>Downloads the FHIR package from a registry</li><li>Generates TypeScript interfaces, validators, and classes</li><li>Compiles the output with <code>tsc</code> (zero errors required)</li><li>Generates <code>empty()</code> and <code>random()</code> test resources for every profile</li><li>Validates those resources against two external FHIR validators</li></ol><h3 id="tested-implementation-guides-30-packages" tabindex="-1">Tested Implementation Guides (30 packages) <a class="header-anchor" href="#tested-implementation-guides-30-packages" aria-label="Permalink to &quot;Tested Implementation Guides (30 packages)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Category</th><th>Implementation Guide</th><th>Package</th><th>FHIR</th></tr></thead><tbody><tr><td>US</td><td>US Core</td><td><code>hl7.fhir.us.core@8.0.0</code></td><td>R4</td></tr><tr><td>US</td><td>QI-Core</td><td><code>hl7.fhir.us.qicore@6.0.0</code></td><td>R4</td></tr><tr><td>US</td><td>mCODE</td><td><code>hl7.fhir.us.mcode@4.0.0</code></td><td>R4</td></tr><tr><td>US</td><td>SDOH Clinical Care</td><td><code>hl7.fhir.us.sdoh-clinicalcare@2.2.0</code></td><td>R4</td></tr><tr><td>US</td><td>NDH (National Directory)</td><td><code>hl7.fhir.us.ndh@1.0.0</code></td><td>R4</td></tr><tr><td>US</td><td>CARIN BB</td><td><code>hl7.fhir.us.carin-bb@2.1.0</code></td><td>R4</td></tr><tr><td>US</td><td>CQF Measures</td><td><code>hl7.fhir.us.cqfmeasures@4.0.0</code></td><td>R4</td></tr><tr><td>US</td><td>Physical Activity</td><td><code>hl7.fhir.us.physical-activity@1.0.0</code></td><td>R4</td></tr><tr><td>DaVinci</td><td>PAS</td><td><code>hl7.fhir.us.davinci-pas@2.0.1</code></td><td>R4</td></tr><tr><td>DaVinci</td><td>CDex</td><td><code>hl7.fhir.us.davinci-cdex@2.1.0</code></td><td>R4</td></tr><tr><td>DaVinci</td><td>PDex</td><td><code>hl7.fhir.us.davinci-pdex@2.1.0</code></td><td>R4</td></tr><tr><td>DaVinci</td><td>DTR</td><td><code>hl7.fhir.us.davinci-dtr@2.1.0</code></td><td>R4</td></tr><tr><td>DaVinci</td><td>Alerts</td><td><code>hl7.fhir.us.davinci-alerts@1.0.0</code></td><td>R4</td></tr><tr><td>DaVinci</td><td>DEQM</td><td><code>hl7.fhir.us.davinci-deqm@4.0.0</code></td><td>R4</td></tr><tr><td>DaVinci</td><td>Drug Formulary</td><td><code>hl7.fhir.us.davinci-drug-formulary@2.1.0</code></td><td>R4</td></tr><tr><td>Universal</td><td>IPS</td><td><code>hl7.fhir.uv.ips@2.0.0</code></td><td>R4</td></tr><tr><td>Universal</td><td>SMART App Launch</td><td><code>hl7.fhir.uv.smart-app-launch@2.2.0</code></td><td>R4</td></tr><tr><td>Universal</td><td>SDC (Structured Data Capture)</td><td><code>hl7.fhir.uv.sdc@3.0.0</code></td><td>R4</td></tr><tr><td>Universal</td><td>Genomics Reporting</td><td><code>hl7.fhir.uv.genomics-reporting@3.0.0</code></td><td>R4</td></tr><tr><td>Universal</td><td>CPG (Clinical Practice Guidelines)</td><td><code>hl7.fhir.uv.cpg@2.0.0</code></td><td>R4</td></tr><tr><td>DE</td><td>ISiK Basis</td><td><code>de.gematik.isik-basismodul@4.0.3</code></td><td>R4</td></tr><tr><td>DE</td><td>ISiK Medikation</td><td><code>de.gematik.isik-medikation@4.0.1</code></td><td>R4</td></tr><tr><td>DE</td><td>KBV eRezept</td><td><code>kbv.ita.erp@1.1.1</code></td><td>R4</td></tr><tr><td>DE</td><td>DE Basisprofil</td><td><code>de.basisprofil.r4@1.5.0</code></td><td>R4</td></tr><tr><td>CH</td><td>CH Core (Switzerland)</td><td><code>ch.fhir.ig.ch-core@5.0.0</code></td><td>R4</td></tr><tr><td>AU</td><td>AU Core (Australia)</td><td><code>hl7.fhir.au.core@1.0.0</code></td><td>R4</td></tr><tr><td>IHE</td><td>PIXm</td><td><code>ihe.iti.pixm@3.0.4</code></td><td>R4</td></tr><tr><td>IHE</td><td>MHD</td><td><code>ihe.iti.mhd@4.2.2</code></td><td>R4</td></tr><tr><td>R5</td><td>AE Research (R5)</td><td><code>hl7.fhir.uv.ae-research-ig@1.0.1</code></td><td>R5</td></tr><tr><td>R5</td><td>eMedicinal Product (R5)</td><td><code>hl7.fhir.uv.emedicinal-product-info@1.0.0</code></td><td>R5</td></tr></tbody></table><h3 id="firely-sdk-validator" tabindex="-1">Firely SDK Validator <a class="header-anchor" href="#firely-sdk-validator" aria-label="Permalink to &quot;Firely SDK Validator&quot;">​</a></h3><p>The first pipeline validates generated resources using the <a href="https://docs.fire.ly/projects/Firely-NET-SDK/validation.html" target="_blank" rel="noreferrer">Firely SDK Validator</a> — NuGet package <code>Firely.Fhir.Validation.R4</code> (v3.x), running on the <a href="https://docs.fire.ly/projects/Firely-NET-SDK/" target="_blank" rel="noreferrer">Firely .NET SDK</a> <code>Hl7.Fhir.R4</code> (v6.x).</p><p>These are two separate packages on separate version lines, and the report shows both. A validator version of 3.x alongside an SDK version of 6.x is expected — it does not mean the SDK is out of date.</p><p>The pipeline always validates against the <strong>newest</strong> release of each, matching how it always runs the newest HL7 Java Validator. <a href="https://github.com/babelfhir-ts/BabelFHIR-TS/blob/main/scripts/firely-validator/FirelyValidator.csproj" target="_blank" rel="noreferrer"><code>FirelyValidator.csproj</code></a> declares major-bounded floating ranges (<code>3.*</code>, <code>6.*</code>) and carries no lock file, so every CI restore re-resolves them. The exact versions a given run used are recorded in the report header.</p><div class="warning custom-block"><p class="custom-block-title">Known Firely SDK Issues</p><p>52 profiles are excluded from Firely validation due to schema loading or parser bugs in the Firely SDK, or to defects in the profiles themselves. See <a href="#firely-sdk-exclusions">Firely SDK Exclusions</a> below.</p></div><h3 id="hl7-java-validator" tabindex="-1">HL7 Java Validator <a class="header-anchor" href="#hl7-java-validator" aria-label="Permalink to &quot;HL7 Java Validator&quot;">​</a></h3><p>The second pipeline validates using the <a href="https://confluence.hl7.org/display/FHIR/Using+the+FHIR+Validator" target="_blank" rel="noreferrer">official HL7 FHIR Validator</a> (v6.10.3), the reference implementation for FHIR conformance checking.</p><div class="warning custom-block"><p class="custom-block-title">Known HL7 Validator Issues</p><p>27 profiles are excluded from HL7 validation due to terminology server limitations, profile resolution failures, missing snapshots, or cross-profile validation issues. See <a href="#hl7-java-validator-exclusions">HL7 Java Validator Exclusions</a> below.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Terminology validation requires a tx server. The pipeline uses <code>--tx-server https://tx.fhir.org/r4</code> during generation to expand ValueSets and produce valid codes.</p></div><p>📊 <strong><a href="https://babelfhir-ts.github.io/parity-report/" target="_blank" rel="noreferrer">Full Parity Report</a></strong></p><h2 id="firely-sdk-exclusions" tabindex="-1">Firely SDK Exclusions <a class="header-anchor" href="#firely-sdk-exclusions" aria-label="Permalink to &quot;Firely SDK Exclusions&quot;">​</a></h2><p>52 profiles are excluded from Firely validation statistics because they fail for reasons outside the generated code: bugs in the Firely SDK Validator&#39;s profile/schema loading or parser, or a discriminator in the published profile that no instance can satisfy.</p><h3 id="discriminator-loading-failures" tabindex="-1">Discriminator Loading Failures <a class="header-anchor" href="#discriminator-loading-failures" aria-label="Permalink to &quot;Discriminator Loading Failures&quot;">​</a></h3><p>The Firely SDK cannot evaluate complex discriminator expressions in certain StructureDefinitions (<code>fixed[x]</code>/<code>pattern[x]</code>/<code>resolve()</code> errors). <strong>15 profiles</strong> across 4 IGs:</p><table tabindex="0"><thead><tr><th>Package</th><th>Profiles</th><th>Error Pattern</th></tr></thead><tbody><tr><td>ISiK Basis</td><td>ISiKOrganisation, ISiKOrganisationFachabteilung, ISiKAngehoeriger, ISiKPersonImGesundheitsberuf, ISiKPatient</td><td><code>discriminator should have a &#39;fixed[x]&#39;, &#39;pattern[x]&#39; or binding element</code></td></tr><tr><td>IPS</td><td>CompositionUvIps, DiagnosticReportUvIps, BundleUvIps</td><td><code>discriminator path &#39;resolve()&#39;</code> — FHIR R4 spec explicitly supports this</td></tr><tr><td>CH Core</td><td>CHCorePractitioner, CHCorePractitionerEPR, CHCorePatient, CHCorePatientEPR</td><td><code>Failed to load &#39;ch-core-address&#39;</code> — compound discriminator on Extension</td></tr><tr><td>DaVinci PAS</td><td>PASClaimBase, PASClaim, PASClaimUpdate, PASClaimInquiry, PASRequestBundle, PASInquiryRequestBundle</td><td><code>Failed to load</code> — discriminator evaluation failure</td></tr></tbody></table><h3 id="parser-ordering-bug" tabindex="-1">Parser Ordering Bug <a class="header-anchor" href="#parser-ordering-bug" aria-label="Permalink to &quot;Parser Ordering Bug&quot;">​</a></h3><p>The Firely SDK reports false element ordering errors (<code>coding</code> vs <code>text</code>) when parsing against certain profiles. The same resources validate without errors against base FHIR resource types. <strong>5 profiles:</strong></p><table tabindex="0"><thead><tr><th>Package</th><th>Profiles</th></tr></thead><tbody><tr><td>ISiK Basis</td><td>ISiKDiagnose, ISiKProzedur</td></tr><tr><td>DaVinci PAS</td><td>PASEncounter, PASDeviceRequest, PASTask</td></tr></tbody></table><h3 id="resolve-discriminators" tabindex="-1"><code>resolve()</code> Discriminators <a class="header-anchor" href="#resolve-discriminators" aria-label="Permalink to &quot;\`resolve()\` Discriminators&quot;">​</a></h3><p>FHIR R4 lists <code>resolve()</code> as a legal discriminator path, and eight profiles use it to slice a reference by the profile its target conforms to. Firely rejects the path and abandons the schema, then validates against the base resource type. <strong>8 profiles:</strong></p><table tabindex="0"><thead><tr><th>Package</th><th>Profiles</th><th>Element</th></tr></thead><tbody><tr><td>IPS</td><td>CompositionUvIps, DiagnosticReportUvIps</td><td><code>Composition.section:sectionMedications.entry</code>, <code>DiagnosticReport.result</code></td></tr><tr><td>Physical Activity</td><td>PAConditionLowPA, PADiagnosticReport, PAGoal</td><td><code>Condition.evidence.detail</code>, <code>DiagnosticReport.result</code>, <code>Goal.addresses</code></td></tr><tr><td>SDOH</td><td>SDOHCCCondition, SDOHCCTaskForPatient</td><td><code>Condition.evidence.detail</code>, <code>Task.partOf</code></td></tr><tr><td>mCODE</td><td>TNMStageGroup</td><td><code>Observation.hasMember</code> (<code>$this.resolve()</code>)</td></tr></tbody></table><h3 id="snapshot-generator-crash" tabindex="-1">Snapshot Generator Crash <a class="header-anchor" href="#snapshot-generator-crash" aria-label="Permalink to &quot;Snapshot Generator Crash&quot;">​</a></h3><p>Firely&#39;s snapshot generator raises <code>Internal error ... (ElementMatcher.constructChoiceTypeMatch): choice type of diff does not occur in snap</code> for the NDH Practitioner profiles, naming the same path on both sides of the comparison. <strong>3 profiles:</strong> NdhPractitioner, NdhNdApiPractitioner, NdhPnLdApiPractitioner.</p><h3 id="unmatchable-discriminators-in-the-profile" tabindex="-1">Unmatchable Discriminators in the Profile <a class="header-anchor" href="#unmatchable-discriminators-in-the-profile" aria-label="Permalink to &quot;Unmatchable Discriminators in the Profile&quot;">​</a></h3><p>Six profiles slice on a value discriminator whose slice sets no <code>fixed[x]</code>, <code>pattern[x]</code> or binding, so no instance can ever satisfy it. Firely refuses to build the schema and validates the resource against its base type instead, reporting only the base type&#39;s required elements. The defect is in the published StructureDefinition, not in the validator:</p><table tabindex="0"><thead><tr><th>Package</th><th>Profiles</th><th>Discriminator</th></tr></thead><tbody><tr><td>CPG</td><td>CHFBodyWeight, CHFO2Sat, CHFPotassium</td><td><code>Observation.category</code> slice</td></tr><tr><td>AU Core</td><td>AUCorePathologyResult</td><td><code>Observation.category:specificDiscipline.coding.code</code></td></tr><tr><td>SDOH</td><td>SDOHCCObservationRaceOMB, SDOHCCObservationEthnicityOMB</td><td><code>Observation.component:*Description.value[x]</code></td></tr><tr><td>DaVinci PAS</td><td>PASClaimBase, PASClaim, PASClaimInquiry, PASClaimUpdate</td><td><code>Claim.careTeam:OverallClaimMember</code> — value discriminator on a <code>boolean</code></td></tr><tr><td>ISiK Basis</td><td>ISiKAngehoeriger</td><td><code>RelatedPerson.name:Name</code> — pattern discriminator with no pattern</td></tr><tr><td>IHE MHD</td><td>FindDocumentReferencesResponse</td><td><code>Bundle.entry:DocumentReference</code> — discriminator always succeeds</td></tr><tr><td>AU Core</td><td>AUCoreBloodPressure</td><td><code>Observation.component:SystolicBP.code</code> — coding sliced to more than one choice</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Both validators exclude profiles independently. Some profiles (e.g. ISiKOrganisation, ISiKPatient) are excluded from <strong>both</strong> pipelines for different reasons.</p></div><h2 id="keeping-the-exclusion-list-honest" tabindex="-1">Keeping the Exclusion List Honest <a class="header-anchor" href="#keeping-the-exclusion-list-honest" aria-label="Permalink to &quot;Keeping the Exclusion List Honest&quot;">​</a></h2><p>Every exclusion records a <em>diagnosis</em>, and diagnoses go stale: the validator ships a fix, or an earlier harness bug turns out to have been the real cause. A stale entry is worse than no entry, because the report reads as parity while the check is simply not happening.</p><p><a href="https://github.com/babelfhir-ts/BabelFHIR-TS/blob/main/scripts/audit-parity-exclusions.mjs" target="_blank" rel="noreferrer"><code>scripts/audit-parity-exclusions.mjs</code></a> replays a run&#39;s recorded comparisons through the harness&#39;s own comparator, once with each exclusion applied and once without, and sorts every entry into <em>obsolete</em> (passes without it — delete), <em>load-bearing</em> (passes only with it — keep), <em>ineffective</em> (fails either way — the reason no longer describes what happens) or <em>unmeasured</em>.</p><h3 id="the-re-check-protocol" tabindex="-1">The re-check protocol <a class="header-anchor" href="#the-re-check-protocol" aria-label="Permalink to &quot;The re-check protocol&quot;">​</a></h3><ol><li><strong>Audit at least two runs.</strong> Three entries read obsolete against a single run, were deleted, and failed in the next one.</li><li><strong>A run count does not settle a terminology-dependent finding.</strong> Those same three then read obsolete across two consecutive runs and were still live, because whether the HL7 validator reports them depends on what the terminology server answers that day. Entries like that carry <code>intermittent: true</code> and the audit refuses to propose them for deletion. Flag an entry that behaves this way rather than deleting it a second time.</li><li><strong>Measure profile-level entries deliberately.</strong> Run the pipeline with <code>PARITY_AUDIT_EXCLUSIONS=1</code>, which switches every curated exclusion off, so the suppressed comparisons actually run. Those numbers are diagnostic only and must never be published as the pipeline&#39;s own.</li><li><strong>Check the version spread.</strong> The audit prints how many entries are pinned to each validator version. Anything older than the version in the run report has not been re-verified since.</li><li><strong>Deleting is the risky direction.</strong> Keeping a live entry costs one tolerated field; deleting one costs a red pipeline. When in doubt, keep it and re-audit.</li></ol><p>Profile-level exclusions come back <em>unmeasured</em> by construction: suppressing the profile suppresses the comparison, so the artifacts cannot say whether the exclusion is still needed. Those have to be audited by re-running with them disabled. Their <code>validatorVersion</code> is deliberately left at the version they were last verified against, so the gap between that and the version in the report is the staleness signal.</p><h2 id="hl7-java-validator-exclusions" tabindex="-1">HL7 Java Validator Exclusions <a class="header-anchor" href="#hl7-java-validator-exclusions" aria-label="Permalink to &quot;HL7 Java Validator Exclusions&quot;">​</a></h2><p>27 profiles are excluded from HL7 validation statistics due to terminology server limitations, profile resolution failures, missing snapshots, cross-profile validation, or discriminator evaluation failures.</p><h3 id="profile-resolution-failures" tabindex="-1">Profile Resolution Failures <a class="header-anchor" href="#profile-resolution-failures" aria-label="Permalink to &quot;Profile Resolution Failures&quot;">​</a></h3><p>The HL7 validator cannot resolve profile references needed for slicing evaluation. <strong>7 profiles</strong> in ISiK Basis:</p><table tabindex="0"><thead><tr><th>Profile</th><th>Error Pattern</th></tr></thead><tbody><tr><td>ISiKOrganisation, ISiKOrganisationFachabteilung</td><td><code>Unable to resolve profile</code> (identifier-bsnr)</td></tr><tr><td>ISiKAllergieUnvertraeglichkeit</td><td><code>Unable to resolve profile</code> (CodingASK)</td></tr><tr><td>ISiKPersonImGesundheitsberuf</td><td><code>Unable to resolve profile</code> (identifier-efn)</td></tr><tr><td>ISiKAbrechnungsfall</td><td><code>Unable to resolve profile</code> (identifier-abrechnungsnummer)</td></tr><tr><td>ISiKPatient</td><td><code>Unable to resolve profile</code> (identifier-kvid-10)</td></tr><tr><td>ISiKProzedur</td><td><code>Unable to resolve profile</code> (CodingOPS)</td></tr></tbody></table><h3 id="missing-snapshots" tabindex="-1">Missing Snapshots <a class="header-anchor" href="#missing-snapshots" aria-label="Permalink to &quot;Missing Snapshots&quot;">​</a></h3><p>The HL7 validator reports that certain StructureDefinitions have no snapshot, preventing validation. <strong>3 profiles</strong> in ISiK Basis:</p><table tabindex="0"><thead><tr><th>Profile</th><th>Error Pattern</th></tr></thead><tbody><tr><td>ISiKDiagnose, ISiKVersicherungsverhaeltnisSelbstzahler, ISiKVersicherungsverhaeltnisGesetzlich</td><td><code>has no snapshot - validation is ...</code></td></tr></tbody></table><h3 id="slicing-evaluation-failure" tabindex="-1">Slicing Evaluation Failure <a class="header-anchor" href="#slicing-evaluation-failure" aria-label="Permalink to &quot;Slicing Evaluation Failure&quot;">​</a></h3><p>The HL7 validator cannot match discriminators for <code>$this</code>-based slicing. <strong>1 profile:</strong></p><table tabindex="0"><thead><tr><th>Profile</th><th>Error Pattern</th></tr></thead><tbody><tr><td>ISiKAngehoeriger</td><td><code>Could not match any discriminators ($this) for slice RelatedPerson.name:Name</code></td></tr></tbody></table><h3 id="environment-errors" tabindex="-1">Environment Errors <a class="header-anchor" href="#environment-errors" aria-label="Permalink to &quot;Environment Errors&quot;">​</a></h3><p>The HL7 validator reported internal errors unrelated to the generated resource content. <strong>6 profiles:</strong></p><table tabindex="0"><thead><tr><th>Package</th><th>Profiles</th></tr></thead><tbody><tr><td>ISiK Basis</td><td>ISiKBerichtBundle, ISiKPatientMergeSubscription, ISiKLebensZustand, ISiKCodeSystem</td></tr><tr><td>IPS</td><td>BundleUvIps</td></tr><tr><td>DaVinci PAS</td><td>PASTask</td></tr></tbody></table>`,68)])])}const g=t(o,[["render",s]]);export{u as __pageData,g as default};
